use crate::{Theme, ThemeError, Writer};
use std::path::PathBuf;

pub struct Zathura;

impl Writer for Zathura {
    fn name(&self) -> &'static str {
        "zathura"
    }

    fn output_path(&self) -> PathBuf {
        crate::home().join(".config/zathura/themes/active")
    }

    fn enabled(&self) -> bool {
        crate::app_enabled("zathura", ".config/zathura")
    }

    fn generate(&self, theme: &Theme) -> Result<String, ThemeError> {
        let t = theme;
        let include_path = crate::home().join(".config/zathura/themes/active");
        Ok(format!(
            "# Generated by theme-manager. Do not edit manually.\n\
             # To use: add this line to ~/.config/zathura/zathurarc:\n\
             #   include {}\n\
             #\n\
             set default-bg               \"{}\"\n\
             set default-fg               \"{}\"\n\
             \n\
             set statusbar-bg             \"{}\"\n\
             set statusbar-fg             \"{}\"\n\
             \n\
             set inputbar-bg              \"{}\"\n\
             set inputbar-fg              \"{}\"\n\
             \n\
             set notification-bg          \"{}\"\n\
             set notification-fg          \"{}\"\n\
             set notification-error-bg    \"{}\"\n\
             set notification-error-fg    \"{}\"\n\
             set notification-warning-bg  \"{}\"\n\
             set notification-warning-fg  \"{}\"\n\
             \n\
             set completion-bg            \"{}\"\n\
             set completion-fg            \"{}\"\n\
             set completion-group-bg      \"{}\"\n\
             set completion-group-fg      \"{}\"\n\
             set completion-highlight-bg  \"{}\"\n\
             set completion-highlight-fg  \"{}\"\n\
             \n\
             set index-bg                 \"{}\"\n\
             set index-fg                 \"{}\"\n\
             set index-active-bg          \"{}\"\n\
             set index-active-fg          \"{}\"\n\
             \n\
             set highlight-color          \"{}\"\n\
             set highlight-active-color   \"{}\"\n\
             \n\
             set recolor-lightcolor       \"{}\"\n\
             set recolor-darkcolor        \"{}\"\n",
            include_path.display(),
            t.require("BASE00")?, // default-bg
            t.require("BASE05")?, // default-fg
            t.require("BASE01")?, // statusbar-bg
            t.require("BASE05")?, // statusbar-fg
            t.require("BASE00")?, // inputbar-bg
            t.require("BASE05")?, // inputbar-fg
            t.require("BASE00")?, // notification-bg
            t.require("BASE05")?, // notification-fg
            t.require("BASE00")?, // notification-error-bg
            t.require("BASE08")?, // notification-error-fg
            t.require("BASE00")?, // notification-warning-bg
            t.require("BASE0A")?, // notification-warning-fg
            t.require("BASE01")?, // completion-bg
            t.require("BASE05")?, // completion-fg
            t.require("BASE00")?, // completion-group-bg
            t.require("BASE0D")?, // completion-group-fg
            t.require("BASE0D")?, // completion-highlight-bg
            t.require("BASE00")?, // completion-highlight-fg
            t.require("BASE00")?, // index-bg
            t.require("BASE05")?, // index-fg
            t.require("BASE01")?, // index-active-bg
            t.require("BASE05")?, // index-active-fg
            t.require("BASE0A")?, // highlight-color
            t.require("BASE0D")?, // highlight-active-color
            t.require("BASE00")?, // recolor-lightcolor
            t.require("BASE05")?, // recolor-darkcolor
        ))
    }

    // No reload() override: zathura reads its config only at startup and has
    // no runtime reload signal, so we fall back to the trait's default no-op.
    // The new theme takes effect the next time zathura is launched.
}
